INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 1, 'theory', 'Квиз: анализ сложности');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 0, 'Алгоритм за квадрат переписали на самом быстром языке мира, алгоритм за логарифм остался на самом медленном. Кто выиграет на миллионе элементов?', '["Квадрат на быстром языке — константы решают","Логарифм: около двадцати операций против триллиона — класс роста сильнее языка","Оба примерно одинаково: язык всё уравняет","Зависит от объёма оперативной памяти"]', 1, 'На миллионе элементов логарифм — десятки операций, квадрат — триллионы, и это часы против долей секунды. Класс роста сильнее языка, сильнее железа и любых мелких хитростей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 1, 'Почему библиотечные сортировки переключаются на простые методы на маленьких кусках?', '["Простые методы не требуют дополнительной памяти","Стандарт языка обязывает поддерживать старые алгоритмы","Биг-о отбрасывает константы: на малых данных алгоритм с меньшей константой при худшем классе может обгонять","Сложные алгоритмы не работают на массивах малой длины"]', 2, 'Биг-о отвечает на вопрос «что случится на больших данных», а не «что быстрее на десяти элементах». Оба вопроса законны — важно не путать, на какой из них отвечает каждая мера.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 2, 'Быстрая сортировка на уже отсортированных данных выбирает опорой первый элемент. Что произойдёт?', '["Каждое разделение раскалывает массив на одиночку и всё остальное — сложность сползает в квадрат","Сортировка завершится за линейное время: данные уже упорядочены","Ничего не изменится: сложность останется эн лог эн","Обязательно переполнится стек рекурсии"]', 0, 'Глубина рекурсии становится линейной. Спасения три: случайная опора, медиана из трёх или интроспективный подход с переключением на сортировку без плохих данных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 3, 'Фраза «словарь работает за константу» опасна в каком случае?', '["Если ключи — короткие строки","Если таблица только что создана и пуста","Если операций с таблицей немного","Если по вашим ключам всё сгружается в одно ведро — поиск становится линейным"]', 3, 'Усреднённая константа при редком линейном провале — нормальная сделка, если провал вам не встретится, и опасная, если по вашим ключам провал гарантируется.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 1, 4, 'Динамический массив иногда тратит линейное время на добавление, но считается константным. Почему это честно?', '["Потому что копирование выполняется специальной быстрой командой процессора","Потому что редкие дорогие копирования, размазанные на множество вставок, в среднем дают константу","Потому что память под массив выделяется далеко вперёд","Потому что копирование не входит в сложность операции"]', 1, 'Амортизационный анализ делит суммарную работу на число операций. Та же логика у хеш-таблиц при переезде и у сборщиков мусора.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 2, 'theory', 'Квиз: массивы и строки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 0, 'Массив начинается с адреса 2000, элемент занимает 4 байта. По какому адресу лежит элемент с индексом 10?', '["2010","2040","2044","Нужно пройти десять элементов, чтобы узнать"]', 1, 'Адрес = начало + индекс × размер = 2000 + 10 · 4 = 2040. Одно умножение и одно сложение, поэтому доступ по индексу не зависит от длины массива.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 1, 'Динамический массив при заполнении увеличивает ёмкость на 10 клеток, а не вдвое. Что произойдёт на миллионе добавлений?', '["Ничего: стоимость добавления всё равно амортизированная константа","Память кончится раньше, чем время","Суммарная работа копирования вырастет до квадратичной","Массив станет медленнее при чтении по индексу"]', 2, 'Копирований будет сто тысяч, и каждое тянет всё накопленное: десятки миллиардов операций. При удвоении сумма копирований 1 + 2 + 4 + … меньше 2n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 2, 'В какой позиции массива вставка нового элемента обходится дороже всего?', '["В конце","В середине","В начале","Везде одинаково: сдвиг всегда O(n)"]', 2, 'Вставка в начало сдвигает все n элементов, в середину — половину, в конец — ни одного. Поэтому постоянные вставки в начало — сигнал взять очередь или список.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 3, 'Нужно тысячу раз узнавать сумму на произвольном отрезке массива из миллиона элементов. Что выбрать?', '["Считать сумму циклом по отрезку каждый раз","Отсортировать массив и использовать бинарный поиск","Один раз построить префиксные суммы: ответ — разность двух чисел","Хранить массив в словаре"]', 2, 'Подготовка — один проход, а каждый запрос — две выборки и вычитание. Цикл по отрезку — до миллиарда операций суммарно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 2, 4, 'Почему сборка длинной строки в цикле через s += c может превратиться в квадрат?', '["Конкатенация не умеет работать с юникодом","Строки неизменяемы: каждая приписка копирует всю накопленную строку","Интерпретатор проверяет строку на анаграмму","Каждый символ хранится отдельным объектом в хеш-таблице"]', 1, 'Копируется 1 + 2 + 3 + … символов — это порядка n²/2 операций. Лекарство: копить куски в списке и один раз склеить методом join.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 3, 'theory', 'Квиз: связные списки');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 0, 'Нужно вставить узел X после известного узла B в односвязном списке. Какой порядок присваиваний верен?', '["Сначала B.next = X, затем X.next = B.next","Сначала X.next = B.next, затем B.next = X","Порядок не важен: операции независимы","Сначала удалить B, потом вставить X"]', 1, 'Если первым присвоить B.next = X, прежний хвост списка потеряется: на него больше никто не указывает. Сначала запоминаем хвост в X, потом перенаправляем B.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 1, 'Быстрый указатель дошёл до конца списка из семи узлов, шагая по два. Где в этот момент медленный (шаг по одному)?', '["В первом узле","В третьем узле","В четвёртом узле — середина списка","В шестом узле"]', 2, 'Медленный прошёл ровно половину: при семи узлах быстрый делает три прыжка, медленный — три шага, то есть стоит в четвёртом узле — это середина.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 2, 'Почему в сортировке слиянием связный список выигрывает у массива?', '["Список нельзя разделить пополам, а массив можно","Слияние списков переставляет ссылки и не требует вспомогательного буфера","Сортировка слиянием на списке работает за линейное время","Списки не нуждаются в рекурсии"]', 1, 'Слияние двух отсортированных списков — перенос узлов в результат без копирования; массиву для слияния нужен буфер длины n. Время при этом остаётся n лог n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 3, 'В кольцевом буфере голова равна хвосту. Что это означает?', '["Очередь пуста","Очередь полна","По одним индексам нельзя сказать: нужен счётчик занятых мест или лишняя клетка","Произошла ошибка: так быть не может"]', 2, 'Оба состояния — пустая и заполненная очередь — дают равные индексы. Поэтому хранят число занятых мест (или всегда оставляют одну клетку свободной).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 4, 'Почему очередь из двух стопок даёт амортизированную константу на снятие, хотя перелив стоит линейное время?', '["Перелив происходит на каждом снятии, но очень быстро","Каждый элемент переливается не больше одного раза за всё время жизни","Вторая стопка всегда пуста","Перелив выполняется параллельно с вставкой"]', 1, 'Элемент попадает во входную стопку, один раз переливается в выходную и снимается. Дорогая операция оплачена множеством дешёвых — амортизированный анализ из главы про сложность.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 4, 'theory', 'Квиз: поиск и сортировка');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 0, 'Почему бинарный поиск не работает на связном списке, даже упорядоченном?', '["Потому что списки не поддерживают сравнение элементов","Потому что список нельзя обойти дважды","Потому что доступ к середине требует линейного прохода — вся экономия улетучивается","Потому что бинарный поиск работает только с числами"]', 2, 'Трюк держится на двух требованиях: порядок и константный доступ к любому элементу. Эта же связка лежит в основе индексов баз данных.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 1, 'На почти отсортированных данных какая из элементарных сортировок работает почти за линейное время?', '["Выбор: минимум перестановок","Вставки: каждый элемент сдвигается на одну-две позиции","Пузырёк: равномерные обмены соседей","Ни одна: квадрат есть квадрат"]', 1, 'Именно поэтому вставки живут внутри библиотечных гибридов вроде тимсорта и интроспективной сортировки: на маленьких и почти упорядоченных кусках они царят.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 2, 'Список заказов отсортирован по дате; теперь сортируем его по городу. Что даёт устойчивая сортировка?', '["Внутри каждого города сохранится хронология заказов","Сортировка пройдёт быстрее на уже упорядоченных данных","Дубликаты заказов будут удалены","Порядок по дате сохранится для всей таблицы целиком"]', 0, 'Равные по городу элементы сохраняют исходный порядок. Устойчивость — инструмент, а не деталь: в документации библиотечных сортировок она всегда объявлена явно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 3, 'В чём суть «бинарного поиска по ответу»?', '["Искать значение бинарным поиском в отсортированном массиве данных","Сортировать ответы и сравнивать соседние","Перебирать все возможные ответы от меньшего к большему","Если подходит величина, то и любая меньшая подходит — гуляем бинарным поиском по пространству ответов с линейной проверкой"]', 3, 'Ответ монотонен — значит, вместо перебора сужаем диапазон: логарифм итераций, каждая проверка линейна. Шаблон решает целый класс задач, выглядящих переборными монстрами.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 4, 4, 'Почему умение сливать два отсортированных списка ценнее самой сортировки слиянием?', '["Потому что слияние не требует дополнительной памяти","Потому что слияние устойчивее других операций","Потому что слияние нужно везде: логи двух сервисов, пересечение списков, внешняя сортировка данных с диска","Потому что слияние работает только на магнитных лентах"]', 2, 'Масштабируя приём, получаем внешнюю сортировку: сортируем куски, помещающиеся в память, и сливаем всё более крупные серии. Принцип не изменился за полвека.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 5, 'theory', 'Квиз: хеш-таблицы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 0, 'Таблица из 16 ячеек, номер ячейки — остаток от деления ключа на 16. Что будет, если все ключи кратны 16?', '["Ключи равномерно разойдутся по ячейкам","Все ключи попадут в ячейку 0 — таблица выродится в одну длинную цепочку","Таблица сама увеличится до 32 ячеек","Ничего не изменится: остаток от деления всегда случаен"]', 1, 'Метод деления чувствителен к закономерностям в ключах: кратные размеру ключи падают в одну ячейку. Поэтому берут простой размер или метод умножения, перемешивающий биты.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 1, 'Почему в открытой адресации удалённый ключ нельзя просто стереть из ячейки?', '["Освободившееся место нельзя использовать повторно","Это нарушит порядок ключей в таблице","Пробег оборвётся: поиск ключей, лежащих дальше по пути пробирования, решит, что их нет","Стирание требует перехеширования всей таблицы"]', 2, 'Поиск останавливается на первой пустой ячейке. Надгробие сообщает: «здесь кто-то был, иди дальше», а вставка при этом может занять его место.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 2, 'Что гарантирует корректность хеш-таблицы по отношению к ключам?', '["Если ключи равны, их хеши обязаны быть равны","Если хеши равны, ключи обязаны быть равны","Хеш каждого ключа должен быть уникален","Хеш ключа должен меняться при каждом обращении"]', 0, 'Разные ключи могут иметь равные хеши (коллизия), а вот равные ключи с разными хешами потеряются в таблице — поэтому и изменяемые ключи опасны.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 3, 'Таблица выросла вдвое. Почему ключи нельзя просто скопировать в те же номера ячеек новой таблицы?', '["Новая таблица использует другие хеш-функции","Номер ячейки — остаток от деления на размер, поэтому при новом размере у ключа новый номер: нужно вставить заново","Старые ячейки нельзя освободить","Копирование нарушит коэффициент заполнения"]', 1, 'Хеш ключа тот же, но номер ячейки считается по размеру таблицы. Перехеширование дорогое, но редкое, поэтому амортизированная цена вставки — константа.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 5, 4, 'Для какой задачи хеш-таблица не подходит?', '["Подсчёт частот слов в тексте","Проверка «встречалось ли это число раньше»","Поиск ключа, ближайшего по значению к заданному","Группировка слов по анаграммам"]', 2, 'Хеш не хранит порядок и не умеет находить соседей по значению или диапазоны — для этого нужны упорядоченные структуры, например деревья поиска.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 6, 'theory', 'Квиз: два указателя');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 0, 'Отсортированный массив, ищем пару с суммой 10. Сейчас левый и правый указатели дают сумму 14. Что делаем?', '["Сдвигаем левый указатель вправо","Сдвигаем правый указатель влево","Сдвигаем оба","Начинаем заново с другой пары"]', 1, 'Сумма велика, а уменьшить её можно только взяв меньший правый элемент. Правый элемент в паре с любым левым даст не меньше 14 — его можно отбросить навсегда.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 1, 'В задаче о контейнере с водой нужно сдвинуть один из указателей. Какой?', '["Тот, у которого стенка выше","Тот, у которого стенка ниже","Всегда левый","Тот, что дальше от середины"]', 1, 'Площадь ограничена меньшей стенкой. Сдвиг большей уменьшит ширину, не увеличив ограничивающую высоту, — улучшения быть не может. Двигаем меньшую.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 2, 'Почему приём «два указателя навстречу» для суммы не работает на неотсортированном массиве?', '["Из-за переполнения при сложении","Не гарантируется, что сдвиг указателя изменяет сумму в нужную сторону","Нельзя читать массив с конца","Сложность вырастает до экспоненциальной"]', 1, 'Рассуждение «слишком много — двигаем правый» опирается на то, что правее стоят большие значения. Без сортировки оно ничего не доказывает, и ответ можно потерять.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 3, 'Для чего в задаче о тройках с нулевой суммой пропускают повторяющиеся значения первого элемента?', '["Чтобы ускорить сортировку","Чтобы не получить одинаковые тройки в ответе","Чтобы указатели не вышли за границы массива","Чтобы не переполнить стек"]', 1, 'Если первый элемент повторяет предыдущий, пары для него найдутся те же — тройки продублируются. Пропуск делается сразу после обработки, с проверкой границ.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 6, 4, 'В задаче о голландском флаге (0, 1, 2) средний указатель встретил двойку и поменял её с правой границей. Почему он не сдвигается вперёд?', '["Это ошибка: должен сдвигаться","На месте двойки теперь оказался ещё не просмотренный элемент","Правая граница указывает на ноль","Массив уже отсортирован"]', 1, 'Элемент, пришедший справа, ещё не разобран, поэтому mid остаётся, а двигается только правая граница. При нуле же слева лежит уже проверенный элемент — там сдвигаем оба.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 7, 'theory', 'Квиз: окно и разделяй и властвуй');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 0, 'Почему алгоритм со скользящим окном работает за линейное время, хотя внутри цикла стоит ещё один цикл?', '["Внутренний цикл всегда выполняется один раз","Каждый элемент входит в окно один раз и выходит не больше одного раза — суммарно не более 2n движений границ","Внутренний цикл выполняется параллельно","Интерпретатор оптимизирует вложенные циклы"]', 1, 'Считаем не глубину циклов, а общее число движений границ: правая идёт только вперёд, левая — тоже. Поэтому суммарно порядка 2n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 1, 'Для какой задачи скользящее окно с «поджиманием» левой границы даст неверный ответ?', '["Самая длинная подстрока без повторов","Кратчайший подмассив с суммой не меньше цели, если в массиве есть отрицательные числа","Максимальная сумма k подряд идущих элементов","Анаграммы в строке"]', 1, 'При отрицательных числах расширение окна не гарантирует рост суммы, а сжатие — убывание: пропадает монотонность. Тут нужны префиксные суммы и хеш-таблица.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 2, 'Что хранит монотонная очередь при поиске максимума в окне?', '["Все элементы окна по порядку поступления","Индексы элементов, значения которых убывают; в голове — максимум окна","Только текущий максимум","Отсортированные элементы окна"]', 1, 'Новый элемент выталкивает с конца меньших — они устареют раньше и максимумами не станут. С головы убирают индексы, вышедшие из окна.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 3, 'Задача делится на две половины, а склейка результатов стоит линейное время. Какова общая сложность?', '["O(n)","O(n log n)","O(n²)","O(log n)"]', 1, 'В дереве рекурсии log n уровней, на каждом суммарная работа склейки порядка n — итого n log n, как у сортировки слиянием.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 7, 4, 'Когда разделяй и властвуй — неудачный выбор?', '["Когда подзадачи независимы","Когда подзадачи пересекаются и одни и те же считаются многократно — нужно запоминание (динамическое программирование)","Когда склейка стоит линейное время","Когда задачу можно разделить пополам"]', 1, 'Независимость подзадач — ключевое условие. Пересекающиеся подзадачи без запоминания пересчитываются экспоненциально много раз.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 8, 'theory', 'Квиз: строковые алгоритмы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 0, 'Что хранит значение префикс-функции в позиции i?', '["Номер позиции, где образец встретился в первый раз","Число различных букв в подстроке до позиции i","Длину наибольшего собственного префикса подстроки до i, который равен её суффиксу","Сколько раз префикс повторяется в оставшейся части строки"]', 2, 'Для «abacaba» значения 0, 0, 1, 0, 1, 2, 3: в конце «aba» — это и начало, и конец строки. Именно эти числа подсказывают, на сколько можно сдвинуть образец без потери совпадений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 1, 'Почему поиск Кнута — Морриса — Пратта работает за линейное время даже в худшем случае?', '["Он сортирует текст перед поиском","Указатель по тексту не идёт назад, а откаты по таблице образца в сумме не превосходят шагов вперёд","Он использует хеши и пропускает проверку символов","Он ищет только образцы, не превышающие пяти символов"]', 1, 'Каждый шаг вправо увеличивает длину совпадения не больше чем на единицу, а откаты только уменьшают её. Поэтому откатов всего не больше, чем шагов вправо, — порядка n + m операций.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 2, 'У строки длиной 12 последнее значение префикс-функции равно 8. Чему равен наименьший период?', '["8","3","12","4"]', 3, 'Период — длина минус последнее значение: 12 − 8 = 4. Так как 12 делится на 4 нацело, строка — это один и тот же кусок из четырёх символов, повторённый трижды.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 3, 'Что нужно сделать после того, как хеш окна текста совпал с хешем образца в алгоритме Рабина — Карпа?', '["Ничего: совпадение хешей гарантирует совпадение строк","Увеличить основание хеша и пересчитать окно","Пропустить окно: коллизия означает, что строки заведомо разные","Сравнить сами строки символ за символом, потому что возможны коллизии"]', 3, 'Равные хеши — лишь кандидат: разные строки иногда дают одинаковые значения. Прямая проверка стоит дорого только при редких коллизиях, поэтому в среднем время остаётся линейным.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 4, 'Нужно подсказывать слова по набранной приставке, а ещё исправлять опечатки в запросах. Какие инструменты подойдут?', '["Хеш-таблица для приставок и сортировка для опечаток","Бор для приставок и расстояние Левенштейна для опечаток","Расстояние Левенштейна для приставок и бор для опечаток","Зет-функция для обеих задач"]', 1, 'Бор спускается по буквам приставки и отдаёт поддерево слов. Расстояние Левенштейна измеряет, сколько правок отделяет введённое слово от словарного. Хеш-таблица приставок не знает вовсе.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 9, 'theory', 'Квиз: числовые алгоритмы и биты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 0, 'Почему алгоритм Евклида работает за порядка логарифма шагов?', '["Он перебирает только простые числа","Он делит числа пополам на каждом шаге","Каждые два шага большее число уменьшается хотя бы вдвое","Он использует таблицу заранее вычисленных остатков"]', 2, 'Остаток от деления меньше половины делимого, поэтому через два шага числа становятся хотя бы вдвое меньше. Хуже всего алгоритм работает на соседних числах Фибоначчи — но и там шагов порядка логарифма.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 1, 'Число 3 нужно «разделить» по простому модулю 7. Чем заменить деление на 3?', '["Умножением на 5, потому что 3 · 5 ≡ 1 (mod 7)","Вычитанием 3 из числа и взятием остатка","Умножением на 7 − 3 = 4","Делением на 3 как обычно, а потом остатком"]', 0, 'Делить по модулю — значит умножать на обратный элемент. Для 3 по модулю 7 это 5: 15 = 2·7 + 1. Обратный находят расширенным Евклидом или степенью a^(p−2) по малой теореме Ферма.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 2, 'Сколько примерно умножений нужно, чтобы вычислить a в степени 10^18 быстрым возведением?', '["10^18","Около миллиона — корень из показателя","Около 18","Около 60 — порядка двоичного логарифма показателя"]', 3, 'Показатель 10^18 занимает около 60 двоичных разрядов: столько возведений в квадрат и не больше столько умножений на накопленный результат. По модулю числа при этом не растут.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 3, 'До какого числа достаточно проверять делители, чтобы убедиться, что n простое?', '["До n / 2","До корня из n","До логарифма n","До n − 1, иначе возможна ошибка"]', 1, 'Если у n есть делитель d больше корня, то и n / d — делитель, и он меньше корня. Значит, любой составной n имеет делитель не больше корня.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 4, 'Чему равно x & (x − 1) для x = 44 (двоичное 101100) и что это значит?', '["44 — число не изменилось, потому что оно чётное","4 — остались только младшие нули","40 — сброшена младшая единица","45 — добавлена единица справа"]', 2, 'x − 1 превращает младшую единицу в ноль, а нули под ней — в единицы, и «и» с x оставляет число без младшей единицы: 101000 = 40. Нулевой результат означает, что число было степенью двойки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 10, 'theory', 'Квиз: деревья и обходы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 0, 'Полное бинарное дерево хранится в массиве, корень на месте 0. Где лежат дети узла с номером 5?', '["Места 6 и 7","Места 10 и 11","Места 11 и 12","Места 9 и 10"]', 2, 'Дети узла i — на местах 2i + 1 и 2i + 2: для i = 5 это 11 и 12. Поэтому куча обходится без ссылок.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 1, 'Какой обход в глубину перечисляет значения двоичного дерева поиска по возрастанию?', '["Прямой (узел, левое, правое)","Центрированный (левое, узел, правое)","Обратный (левое, правое, узел)","Обход в ширину"]', 1, 'Правило дерева поиска — слева меньшие, справа большие: центрированный порядок посещает левое поддерево, потом узел, потом правое — то есть всё по возрастанию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 2, 'Почему для очень глубоких деревьев обходы пишут с явным стеком, а не рекурсией?', '["Явный стек всегда быстрее по времени","Рекурсия использует стек вызовов, глубина которого равна высоте дерева — на цепочке он переполнится","Рекурсия не умеет обходить правое поддерево","Явный стек потребляет меньше памяти на любом дереве"]', 1, 'Вырожденное дерево из ста тысяч узлов — это цепочка высотой в сто тысяч; рекурсивный обход упадёт, а явный стек живёт в обычной памяти.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 3, 'Какая структура данных нужна обходу в ширину?', '["Стек","Очередь","Хеш-таблица","Куча"]', 1, 'Очередь кладёт детей в хвост и берёт узлы с головы — уровень за уровнем. Заменив очередь стеком, получим обход в глубину.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 4, 'Как вычисляют диаметр дерева за один обход?', '["Для каждого узла запускают отдельный обход","Функция возвращает высоту поддерева, а по пути обновляет максимум суммы высот левого и правого поддеревьев","Сортируют узлы по глубине","Берут удвоенную высоту дерева"]', 1, 'Через узел как верхнюю точку проходит путь длиной «левая высота плюс правая высота». Поддерево возвращает вверх высоту, а лучшую сумму запоминают отдельно.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 11, 'theory', 'Квиз: деревья поиска');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 0, 'Дерево поиска корректно, если...', '["каждый узел больше своего левого ребёнка и меньше правого","для каждого узла все ключи левого поддерева меньше, а правого — больше","корень — медиана всех ключей","высота дерева не больше логарифма числа узлов"]', 1, 'Правило касается всех потомков, а не только детей. Поэтому проверку пишут с границами, которые передаются вниз.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 1, 'Какой ключ заменяет удаляемый узел с двумя детьми?', '["Левый ребёнок","Корень дерева","Преемник — минимум правого поддерева","Случайный лист"]', 2, 'Преемник — ближайший по величине ключ: на его месте порядок сохраняется. Его потом удаляют со старого места, где у него не больше одного ребёнка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 2, 'Ключи вставляют в дерево поиска по возрастанию (1, 2, 3, …, n). Что получится?', '["Идеально сбалансированное дерево","Цепочка высотой n: поиск, вставка и удаление — O(n)","Дерево высотой log n","Ошибка вставки"]', 1, 'Каждый новый ключ больше всех и уходит направо — дерево вырождается в связный список. Для упорядоченных данных нужны самобалансирующиеся деревья.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 3, 'Что остаётся неизменным при вращении?', '["Высота дерева","Порядок ключей в центрированном обходе","Корень","Число листьев"]', 1, 'Вращение — локальная перестройка нескольких ссылок: высота и корень меняются, а центрированный порядок ключей — нет. На этом держатся АВЛ- и красно-чёрные деревья.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 11, 4, 'Что дерево поиска умеет, а хеш-таблица — нет?', '["Искать ключ по значению","Находить ближайший ключ и диапазоны","Добавлять ключи","Хранить пары ключ — значение"]', 1, 'Упорядоченность даёт пол и потолок, преемника, k-й ключ и диапазоны за высоту дерева плюс число ответов; хеш порядка не хранит.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 12, 'theory', 'Квиз: куча и heapq');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 0, 'Куча хранится в списке, корень на месте 0. Где лежат дети узла с номером 3?', '["Места 4 и 5","Места 6 и 7","Места 7 и 8","Места 8 и 9"]', 2, 'Дети узла i — на местах 2i + 1 и 2i + 2: для i = 3 это 7 и 8. Родитель узла i — (i − 1) // 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 1, 'При просеивании вниз элемент меняют с меньшим из двух детей. Почему не с большим?', '["С большим быстрее","Иначе меньший ребёнок окажется под большим родителем — свойство кучи нарушится","Так проще написать код","Разницы нет"]', 1, 'После обмена новый родитель должен быть не больше обоих детей. Поднять нужно меньшего: он не превосходит своего брата и опускаемого элемента.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 2, 'Почему построение кучи из массива снизу вверх (heapify) занимает O(n), а не O(n log n)?', '["Потому что используется сортировка слиянием","Половина узлов — листья и не требует работы, а остальные опускаются в среднем на константу уровней: сумма высот линейна","Потому что компьютер сравнивает сразу несколько элементов","Потому что куча уже отсортирована"]', 1, 'Узлов на высоте h примерно n / 2^(h+1), каждый опускается не больше чем на h уровней: ряд n · Σ h / 2^h сходится к константе, умноженной на n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 3, 'Как получить максимальную кучу на модуле heapq?', '["Вызвать heapq.maxheap()","Класть числа со знаком минус и менять знак при извлечении","Отсортировать список по убыванию","Это невозможно"]', 1, 'heapq умеет только минимальную кучу. Знак минус переворачивает порядок: наименьшее из противоположных чисел — это наибольшее исходное.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 12, 4, 'Нужно хранить k наибольших элементов потока. Какую кучу и какого размера использовать?', '["Максимальную кучу размера n","Минимальную кучу размера k: в корне — самый маленький из k лучших","Максимальную кучу размера k","Две кучи размера n / 2"]', 1, 'Новый элемент сравнивают с корнем минимальной кучи: если больше — вытесняет его. Итог: n log k времени и k памяти.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 13, 'theory', 'Квиз: красно-чёрные деревья');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 0, 'Что гарантируют правила красно-чёрного дерева?', '["Все листья на одной глубине","Высоту не больше 2·log₂(n + 1)","Высоту ровно log₂ n","Отсутствие вращений при вставке"]', 1, 'Чёрная высота одинакова на всех путях, а красные не стоят подряд, поэтому самый длинный путь не более чем вдвое длиннее самого короткого.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 1, 'В красно-чёрное дерево вставляется новый узел. В какой цвет его красят?', '["В чёрный","В красный","В цвет родителя","В цвет дяди"]', 1, 'Красный узел не меняет чёрных высот на путях и может нарушить только правило «красных подряд нет» — это проще исправить.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 2, 'Родитель нового узла красный, а дядя тоже красный. Что делают?', '["Вращают деда","Перекрашивают родителя и дядю в чёрный, деда — в красный, и поднимаются к деду","Удаляют узел","Ничего"]', 1, 'Чёрные высоты не меняются, вращений нет — но красный дед может оказаться под красным родителем, тогда повторяем для него.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 3, 'Какие вращения нужны, если дядя чёрный, а новый узел — правый ребёнок левого родителя?', '["Одно правое вращение деда","Левое вращение родителя, затем правое вращение деда с перекраской","Два левых вращения","Вращения не нужны"]', 1, 'Это излом: вращение родителя превращает его в линию, а затем вращение деда и перекраска завершают вставку — не больше двух вращений.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 13, 4, 'В чём практическое отличие АВЛ-дерева от красно-чёрного?', '["АВЛ быстрее ищет (строже баланс), красно-чёрное дешевле перестраивается при вставках и удалениях","АВЛ не использует вращения","Красно-чёрное дерево не нужно балансировать","Разницы нет"]', 0, 'АВЛ держит высоту около 1,44 log n, красно-чёрное — до 2 log n, зато делает меньше вращений, особенно при удалении.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 14, 'theory', 'Квиз: деревья отрезков и Фенвика');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 0, 'Какой отрезок хранит ячейка с номером 12 в дереве Фенвика (нумерация с единицы)?', '["Элементы с 1 по 12","Только элемент 12","Элементы с 9 по 12 — длина равна младшему биту числа 12, то есть четырём","Элементы с 6 по 12"]', 2, '12 в двоичной — 1100, младший бит равен 4. Ячейка хранит сумму отрезка длиной 4, заканчивающегося в 12: элементы 9, 10, 11 и 12.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 1, 'Как в дереве Фенвика найти сумму первых 11 элементов?', '["Сложить ячейки 1, 2, …, 11","Взять ячейку 11 и умножить на 11","Сложить ячейки 11, 12 и 16: на каждом шаге прибавляем младший бит","Сложить ячейки 11, 10 и 8: на каждом шаге убираем младший бит номера"]', 3, '11 = 1011₂ → 10 = 1010₂ → 8 = 1000₂ → 0: ячейки 11, 10 и 8 покрывают элементы 11, 9–10 и 1–8 — то есть ровно первые одиннадцать.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 2, 'Какое требование к операции отличает дерево отрезков от дерева Фенвика для запроса минимума?', '["Дерево отрезков требует обратимой операции, Фенвик — любой","Минимум нельзя вычислить в дереве, оно годится только для сумм","Фенвик годится для минимума, а дерево отрезков — нет","Минимум не обратим (из минимума префикса нельзя «вычесть» префикс), поэтому подходит дерево отрезков"]', 3, 'Фенвик находит отрезок вычитанием двух префиксов, а для минимума такого вычитания нет. Дерево отрезков не вычитает, а объединяет готовые узлы — достаточно ассоциативности.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 3, 'Зачем нужны ленивые метки в дереве отрезков?', '["Чтобы экономить память на листьях","Чтобы изменять сразу целый отрезок за логарифм, откладывая обновление детей до момента спуска","Чтобы хранить копии массива для отката","Чтобы ускорить построение дерева до линейного времени"]', 1, 'Узел, целиком накрытый изменением, обновляется сразу, а детям остаётся метка-долг. Она передаётся вниз только при спуске, поэтому операция на отрезке не превращается в обход всех элементов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 14, 4, 'Почему разреженная таблица отвечает на запрос минимума за константу, но для суммы так нельзя?', '["Для суммы таблица требует больше памяти, чем для минимума","Минимум считается быстрее суммы на любом процессоре","Два перекрывающихся отрезка длины 2ᵏ допустимы для минимума (идемпотентен), а для суммы перекрытие посчитается дважды","Таблица хранит только минимумы и не умеет суммы по построению"]', 2, 'min(x, x) = x, поэтому перекрытие двух степеней двойки не портит ответ. Для суммы перекрывающаяся часть вошла бы дважды — нужно разбивать отрезок без перекрытия, а это уже логарифм.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 15, 'theory', 'Квиз: графы — обходы и связность');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 0, 'Почему проверка «вершина посещена — значит цикл» даёт ложные срабатывания на ориентированных графах?', '["Два пути, сходящиеся в одну вершину, не образуют кольцо — нужен трёхцветный детектор","Потому что в ориентированных графах нет циклов","Потому что посещённые вершины нельзя помечать повторно","Потому что наивная проверка слишком медленна"]', 0, 'Ребро в серую вершину (текущий путь) означает цикл, ребро в чёрную — нет. Три цвета — стандарт индустрии.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 1, 'Когда обход в ширину находит кратчайшие пути, а когда врёт?', '["Всегда находит: волны не ошибаются","Только в ориентированных графах без петель","Только на деревьях; на общих графах врёт всегда","В невзвешенном графе — минимум шагов; с разными весами врёт: волна по многим коротким дорогам может весить больше одной длинной"]', 3, 'Для весов нужна Дейкстра. Правило выбора: нужен хоть какой-то путь быстро и с минимальной памятью — глубина; нужен кратчайший в невзвешенном — ширина.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 2, 'Как алгоритм Кана обнаруживает цикл в графе зависимостей?', '["Раскрашивает вершины в три цвета","Если в конце ответ короче списка вершин — оставшиеся сидят в цикле","Сравнивает степени захода всех вершин попарно","Запускает обход в ширину от каждой вершины"]', 1, 'Вершины со степенью ноль идут в очередь, их обработка уменьшает степени зависимых. Цикл означает противоречивую систему зависимостей, и алгоритм честно это обнаруживает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 3, 'Когда именно помечать вершины посещёнными при обходе в ширину?', '["После полного завершения обхода","В момент извлечения из очереди","При помещении в очередь — иначе одна вершина попадёт туда несколько раз","Это не имеет значения для корректности"]', 2, 'Поздняя пометка раздувает очередь и портит сложность. Из тех же практических тонкостей: глубокую рекурсию на больших графах заменяют явным стеком.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 15, 4, 'Соцсеть: миллион пользователей, у каждого около сотни друзей. Как хранить граф?', '["Списками смежности: память пропорциональна вершинам плюс рёбрам","Матрицей смежности: константная проверка ребра важнее памяти","Отсортированным массивом пар вершин","Деревом поиска по номерам вершин"]', 0, 'Матрица утонула бы в триллионе пустых клеток. Практическое правило: плотные графы — матрица, разреженные (большинство реальных систем) — списки.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 16, 'theory', 'Квиз: кратчайшие пути и остовы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 0, 'Почему Дейкстра не работает с отрицательными весами?', '["Потому что куча не поддерживает отрицательные приоритеты","Потому что отрицательные веса запрещены в навигации","Жадность опирается на монотонность: с минусами длинный путь с большой отрицательной частью может оказаться короче, а вершины уже закрыты","Потому что отрицательный путь всегда означает ошибку данных"]', 2, 'Дейкстра не пересматривает закрытые вершины. Практический вывод: прежде чем применять, спросите, нет ли в системе скидок, возвратов, отрицательных задержек.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 1, 'Какой бонус делает Беллмана-Форда незаменимым?', '["Он работает быстрее Дейкстры на разреженных графах","После эн проходов продолжающееся улучшение оценок означает достижимый отрицательный цикл","Он не требует хранить граф в памяти","Он находит кратчайшие пути между всеми парами сразу"]', 1, 'Отрицательный цикл — сумма по кругу отрицательна, кратчайшего пути просто не существует. Классическое применение — арбитражные цепочки в валютных курсах.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 2, 'Когда А-стар гарантированно находит кратчайший путь?', '["Всегда — эвристика лишь ускоряет перебор","Когда эвристика равна нулю","Когда граф не содержит циклов","Когда эвристика никогда не завышает расстояние до цели"]', 3, 'Поиск идёт в порядке «пройденное плюс эвристика» и тянется к цели, а не исследует всё подряд. Завышающая эвристика ускоряет ещё сильнее, но ломает гарантию.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 3, 'Как одной волной найти для каждой точки карты ближайшую из двадцати пиццерий?', '["Положить все источники в кучу с нулевой оценкой и запустить один алгоритм","Запустить Дейкстру из каждой пиццерии и объединить результаты","Построить минимальный остов графа дорог","Отсортировать все дороги по длине и идти жадно"]', 0, 'Много источников — та же Дейкстра: волна идёт от всех источников сразу, и каждая вершина узнаёт свою ближайшую. Модификация в одну строчку делает алгоритм гибким.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 16, 4, 'Почему жадность Краскала доказуемо оптимальна?', '["Потому что рёбра сортируются за эн лог эн","Потому что граф всегда связный","Потому что есть свойство жадного выбора и оптимальная подструктура: самое дешёвое безопасное ребро входит в хоть какой-то минимальный остов","Потому что система непересекающихся множеств работает за константу"]', 2, 'Любое другое ребро можно обменять не ухудшив. Общий узор: жадность оптимальна, когда локально лучший шаг не рушит глобальный оптимум.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 17, 'theory', 'Квиз: непересекающиеся множества и перебор');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 0, 'Как в системе непересекающихся множеств проверить, что два элемента в одной группе?', '["Сравнить их номера: у одной группы подряд идущие номера","Найти корни обоих элементов и сравнить: группы совпадают, если корни равны","Пройти весь граф обходом в ширину от первого элемента","Сравнить размеры групп, в которых лежат элементы"]', 1, 'Каждый элемент поднимается по родителям до корня; корень — представитель группы. Два элемента в одной группе тогда и только тогда, когда их корни совпадают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 1, 'Что делает сжатие путей?', '["Удаляет из структуры лишние элементы","Хранит в каждом корне размер группы","Сортирует элементы группы по возрастанию","После поиска перевешивает все элементы пути прямо на корень"]', 3, 'Следующий поиск для этих элементов занимает один шаг. Первый поиск по длинной цепочке остаётся дорогим, но он же выпрямляет дерево, поэтому в среднем операции быстрые.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 2, 'В графе обработали рёбра по одному через union. Что означает ребро, концы которого уже лежат в одной группе?', '["Оно замыкает цикл: вершины уже были соединены другим путём","Оно не имеет веса","Оно соединяет две разные компоненты","Оно лишнее: граф несвязный"]', 0, 'Если концы ребра уже в одной группе, то путь между ними есть, и новое ребро замыкает цикл. Именно на этом построен Краскал: такие рёбра пропускают.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 3, 'Что обязательно делает функция бэктрекинга после рекурсивного вызова?', '["Очищает весь список ответов","Сортирует частичный ответ","Отменяет выбор, возвращая общий частичный ответ в состояние до шага","Возвращается в начало программы"]', 2, 'Шаблон — выбрать, исследовать, отменить. Без отмены общий список накопит мусор от соседних веток, и следующие варианты будут считаться неверно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 17, 4, 'Зачем в задаче о сумме числа сортируют и обрывают цикл, когда число больше остатка?', '["Чтобы ответы выводились по убыванию","Чтобы использовать меньше памяти под список ответов","Потому что рекурсия не работает с неотсортированными числами","Все следующие числа не меньше текущего, значит, тоже не подойдут — ветку можно безопасно обрезать"]', 3, 'После сортировки каждое следующее число не меньше текущего. Если текущее уже больше остатка, остальные тем более — перебирать их бессмысленно. Это и есть отсечение.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 18, 'theory', 'Квиз: динамическое программирование');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 0, 'Почему наивная рекурсия для чисел Фибоначчи чудовищно медленна?', '["Потому что рекурсия в принципе медленнее цикла на каждой итерации","Потому что подзадачи перекрываются: одно число пересчитывается много раз, дерево вызовов растёт экспоненциально","Потому что числа Фибоначчи не помещаются в разрядность","Потому что функция неправильно вызывает себя"]', 1, 'Различных подзадач всего сорок, а вызовов — миллиарды. Перекрывающиеся подзадачи плюс сборка ответа из меньших — родовые признаки задач, лечащихся динамикой.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 1, 'Робот на сетке собирает монеты. Почему состояние «позиция плюс число уже собранных монет» не годится?', '["Потому что позиций слишком много для таблицы","Потому что монеты могут быть отрицательными","Потому что состояние должно быть числовым","Потому что число собранных монет неизвестно в момент входа в клетку — накопление живёт в значении, а не в состоянии"]', 3, 'В состояние включайте только то, что влияет на будущее и известно в момент входа. Верное состояние — только позиция, а значение — максимум монет на пути до неё.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 2, 'Почему жадность «брать самое ценное на килограмм» не решает целый рюкзак?', '["Тяжёлый слиток может стоить дороже горсти колец, но не влезть — локально лучший выбор рушит глобальный оптимум","Потому что деление с плавающей точкой неточно","Потому что рюкзак не имеет фиксированной ёмкости","Потому что предметы нельзя упорядочить по ценности"]', 0, 'Это прививка от легкомысленной жадности. Честная динамика — таблица по предметам и ёмкости, каждый ответ выбирает лучший из двух вариантов.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 3, 'Когда в динамике хватит двух рядов таблицы вместо всей?', '["Если все значения в таблице положительные","Если задача решается и жадным алгоритмом","Если переход смотрит только в предыдущий ряд","Если размер таблицы меньше тысячи клеток"]', 2, 'Квадрат превращается в линейную память. Направление обхода — часть решения: в рюкзаке ошибка в направлении — самая популярная ошибка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 4, 'В чём состояние алгоритма Кадане (максимальная сумма подряд идущих)?', '["Сумма всех элементов до текущей позиции","Лучший кусок, оканчивающийся ровно на текущей позиции: продолжить предыдущий или начать заново","Максимальный элемент всего массива","Длина самого длинного возрастающего куска"]', 1, 'Один проход, константная память, ответ — максимум по всем позициям. Без идеи состояния решение выглядит как фокус.');
INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 19, 'theory', 'Квиз: жадные алгоритмы и эвристики');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 0, 'В задаче выбора заявок почему сортируют по времени конца, а не по времени начала?', '["Ранний конец освобождает зал как можно скорее; жадность по началу блокируется длинным ранним событием","По времени конца сортировка быстрее и стабильнее","Время начала ненадёжно и часто неизвестно","Так требует свойство оптимальной подструктуры интервалов"]', 0, 'Контрпример для жадности по началу: длинное событие блокирует весь день, хотя пропуск его даёт кучу коротких. Выбор заявок — шаблон для десятков задач.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 1, 'Набор монет 1, 3, 4, сумма 6. Почему жадность «брать крупнейшую» врёт?', '["Потому что монета 4 слишком крупная для суммы 6","Потому что жадность не работает на чётных суммах","Она отдаст 4+1+1 — три монеты против правильных 3+3 — двух: произвольные номиналы ломают жадность","Потому что сумму 6 нельзя выдать этим набором"]', 2, 'Один новый номинал сломал интуицию. Жадность зависит не только от задачи, но и от конкретных данных; произвольные номиналы превращают размен в динамику по суммам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 2, 'Фракционный рюкзак решается жадностью, целый — нет. Что решает судьбу метода?', '["Размер рюкзака относительно предметов","Делимость предметов: возможность дробить ресурс открывает дверь простым решениям","Порядок, в котором предметы поступают на вход","Количество различных ценностей среди предметов"]', 1, 'Один тумблер — и та же жадность из оптимальной становится ошибочной. Прежде чем выбирать алгоритм, спросите, какие свободы дают данные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 3, 'Как инженерно проверить жадную стратегию, не пишя доказательства?', '["Прогнать её на больших случайных данных и сравнить время","Проверить на отсортированных входных данных","Сравнить с другим жадным алгоритмом на той же задаче","Искать контрпример на маленьком случае вручную; нашёлся — переходить к динамике"]', 3, 'Десять минут ручного перебора на бумаге экономят недели разбора продакшн-инцидента. Жадность и динамика — две стороны одной медали.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 19, 4, 'Что такое инвариант жадного алгоритма?', '["Свойство, которое стратегия сохраняет после каждого шага; если оно переживает первый шаг — жадность почти наверняка корректна","Минимальный элемент, с которого начинается решение","Гарантированная верхняя граница времени работы","Число шагов до первого улучшения решения"]', 0, 'В выборе заявок инвариант звучит так: зал освобождается не позже, чем при любом другом выборе. Инвариант, сломавшийся на втором шаге, — и есть контрпример.');
